export interface DemoTransaction {
  /** Month offset relative to the current month (0 = current). */
  m: number
  d: number
  type: 'income' | 'expense'
  amountCents: number
  description: string
  merchant?: string
  category: string
  member: DemoMember
  scope: TransactionScope
  visibility?: TransactionVisibility
  account?: string
  card?: string
  source?: TransactionSource
  recurring?: string
  installment?: { key: string; number: number; count: number; totalCents: number }
  notes?: string
}

/** Month-by-month variation so the evolution chart tells a plausible story. */
const VARIATION: Record<number, number> = { [-5]: 0.94, [-4]: 1.02, [-3]: 1.06, [-2]: 0.95, [-1]: 1.09, [0]: 1 }

function vary(cents: number, m: number, salt: number): number {
  const factor = (VARIATION[m] ?? 1) + ((salt % 7) - 3) / 100
  return Math.max(100, Math.round((cents * factor) / 10) * 10)
}

