export const DEMO_MONTHS = [-5, -4, -3, -2, -1, 0]

export function demoTransactions(): DemoTransaction[] {
  const out: DemoTransaction[] = []
  for (const m of DEMO_MONTHS) {
    for (const rule of Object.entries(DEMO_RECURRING)) {
      const [key, r] = rule
      out.push({
        m,
        d: r.day,
        type: r.type,
        amountCents: r.amountCents,
        description: r.description,
        category: r.category,
        member: r.member,
        scope: r.scope,
        account: r.account,
        card: r.card,
        source: 'recurring',
        recurring: key,
      })
    }
    MONTHLY_PATTERN.forEach((row, i) => {
      out.push({ ...row, m, amountCents: vary(row.amountCents, m, i + m * 3) })
    })
  }
  out.push(...ONE_OFFS)
  for (const p of INSTALLMENT_PURCHASES) {
    const base = Math.floor(p.totalCents / p.count)
    const remainder = p.totalCents - base * p.count
    for (let i = 0; i < p.count; i++) {
      out.push({
        m: p.m + i,
        d: p.d,
        type: 'expense',
        amountCents: i === 0 ? base + remainder : base,
        description: p.description,
        merchant: p.merchant,
        category: p.category,
        member: p.member,
        scope: p.scope,
        card: p.card,
        installment: { key: p.key, number: i + 1, count: p.count, totalCents: p.totalCents },
      })
    }
  }
  return out
}

